                        %dw 2.0
// aforo-script: config
// The policy properties, normalised once per call. Nothing here throws on a
// bad value: it falls back to the default and says so in "warnings".
output application/java
var DEFAULT_EXCLUDE_PATHS = ["/health", "/ready", "/metrics"]
var DEFAULT_EXCLUDE_STATUS_CODES = [401, 403, 429]
var OUTCOMES = ["SUCCESS", "PARTIAL", "TIMEOUT", "ERROR", "VALIDATION_FAILED", "FAILED",
  "FAILURE", "CANCELLED", "PENDING", "BLOCKED", "HITL_REQUIRED"]
// Lua character classes as Java regex set contents.
var LUA = {
  a: "A-Za-z", d: "0-9", l: "a-z", u: "A-Z", w: "A-Za-z0-9", x: "0-9A-Fa-f",
  s: "\\x20\\t\\n\\r\\f\\x0B", c: "\\x00-\\x1F\\x7F",
  p: "\\x21-\\x2F\\x3A-\\x40\\x5B-\\x60\\x7B-\\x7E", g: "\\x21-\\x7E"
}
fun prop(v) = if (v is String) trim(v replace /^=/ with "") else ""
fun flag(v, dflt) = do {
  var t = lower(prop(v))
  ---
  if (t == "true") true else if (t == "false") false else dflt
}
fun bounded(v, dflt, lo, hi) = do {
  var t = prop(v)
  var n = if (t matches /[0-9]{1,9}/) (t as Number) else dflt
  ---
  if (n < lo) lo else if (n > hi) hi else n
}
fun origin(url) = do {
  var m = url scan /^(https?:\/\/[^\/?#]+)/
  ---
  if (isEmpty(m)) "" else m[0][1]
}
fun csv(v) = ((prop(v) splitBy ",") map trim($)) filter ($ != "")
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""

// ── metric-mappings: Kong's Lua patterns, translated to Java regex ──
// string.find semantics: unanchored unless the pattern starts with ^. %b, %f
// and back-references are not supported; such a rule is skipped.
fun rxEscape(ch) = if ("\\^\$.|?*+()[]{}/-&" contains ch) ("\\" ++ ch) else ch
fun setEscape(ch) = if ("\\]^[-&" contains ch) ("\\" ++ ch) else ch
fun luaClass(ch) = do {
  var lc = lower(ch)
  var cls = LUA[lc]
  ---
  if (cls != null)
    (if (ch == lc) {inner: cls, outer: "[" ++ cls ++ "]"} else {inner: null, outer: "[^" ++ cls ++ "]"})
  else if (ch matches /[A-Za-z0-9]/) null
  else {inner: setEscape(ch), outer: rxEscape(ch)}
}
fun st(out, pending, mode, set, first, err) =
  {out: out, pending: pending, mode: mode, set: set, first: first, err: err}
fun flush(s) = s.out ++ (s.pending default "")
fun luaStep(s, i, cs, n) = do {
  var ch = cs[i]
  var nxt = if (i + 1 < n) cs[i + 1] else null
  ---
  if (s.err) s
  else if (s.mode == "pct") do {
    var c = luaClass(ch)
    ---
    if (c == null) st(s.out, null, s.mode, s.set, s.first, true) else st(s.out, c.outer, "normal", "", false, false)
  }
  else if (s.mode == "setpct") do {
    var c = luaClass(ch)
    ---
    if ((c == null) or (c.inner == null)) st(s.out, null, s.mode, s.set, s.first, true)
    else st(s.out, null, "set", s.set ++ c.inner, false, false)
  }
  else if (s.mode == "set")
    (if ((ch == "^") and (s.set == "[")) st(s.out, null, "set", "[^", true, false)
    else if ((ch == "]") and (not s.first)) st(s.out, s.set ++ "]", "normal", "", false, false)
    else if (ch == "%") st(s.out, null, "setpct", s.set, s.first, false)
    else if ((ch == "-") and (not s.first) and (nxt != null) and (nxt != "]")) st(s.out, null, "set", s.set ++ "-", false, false)
    else st(s.out, null, "set", s.set ++ setEscape(ch), false, false))
  else if ((s.pending != null) and (["*", "+", "?"] contains ch)) st(s.out ++ s.pending ++ ch, null, "normal", "", false, false)
  else if ((s.pending != null) and (ch == "-")) st(s.out ++ s.pending ++ "*?", null, "normal", "", false, false)
  else do {
    var out = flush(s)
    ---
    if (ch == "%") st(out, null, "pct", "", false, false)
    else if (ch == "[") st(out, null, "set", "[", true, false)
    else if (ch == ".") st(out, "[\\s\\S]", "normal", "", false, false)
    else if ((ch == "^") and (i == 0)) st(out ++ "^", null, "normal", "", false, false)
    else if ((ch == "\$") and (i == n - 1)) st(out ++ "\$", null, "normal", "", false, false)
    else if ((ch == "(") or (ch == ")")) st(out ++ ch, null, "normal", "", false, false)
    else st(out, rxEscape(ch), "normal", "", false, false)
  }
}
fun luaToRegex(p) =
  if ((not (p is String)) or (p == "") or (sizeOf(p) > 512)) null
  else do {
    var cs = p splitBy ""
    var n = sizeOf(cs)
    var final = (0 to n - 1) reduce ((i, s = st("", null, "normal", "", false, false)) -> luaStep(s, i, cs, n))
    var rx = if (final.err or (final.mode != "normal")) null else flush(final)
    ---
    if ((rx != null) and dw::Runtime::try(() -> ("" contains (rx as Regex))).success) rx else null
  }
var mappingsText = prop(vars.aforoPropMetricMappings)
var mappingsParsed = if (mappingsText == "") [] else (dw::Runtime::try(() -> read(mappingsText, "application/json")).result default "invalid")
var mappingRules = (if (mappingsParsed is Array) mappingsParsed else []) map ((r) -> do {
  var rule = if (r is Object) r else {}
  var pattern = rule.pathPattern default rule.path_pattern
  ---
  {
    pathPattern: pattern,
    method: upper(trim(str(rule.method))),
    metricName: trim(str(rule.metricName default rule.metric_name)),
    re: luaToRegex(pattern)
  }
})
var metricRules = (mappingRules filter ((r) -> (r.metricName != "") and (r.re != null)))
  map ((r) -> {method: r.method, metricName: r.metricName, re: r.re})
var badRules = mappingRules filter ((r) -> (r.metricName == "") or (r.re == null))

// ── status-outcomes: {"404":"VALIDATION_FAILED"} or 404=VALIDATION_FAILED,... ──
var outcomesText = prop(vars.aforoPropStatusOutcomes)
var outcomePairs =
  if (outcomesText startsWith "{") do {
    var o = dw::Runtime::try(() -> read(outcomesText, "application/json")).result
    ---
    if (o is Object) (o pluck ((v, k) -> [k as String, str(v)])) else []
  }
  else (csv(vars.aforoPropStatusOutcomes) map ((e) -> (e splitBy "=") map trim($)))
    filter ((kv) -> sizeOf(kv) == 2)
var statusOutcomes = outcomePairs reduce ((kv, acc = {}) -> do {
  var code = trim(kv[0] default "")
  var outcome = upper(trim(kv[1] default ""))
  ---
  if ((code matches /[2-5][0-9][0-9]/) and (OUTCOMES contains outcome)) ((acc - code) ++ {(code): outcome}) else acc
})

var endpoint = prop(vars.aforoPropAforoEndpoint)
var apiKey = prop(vars.aforoPropAforoApiKey)
var productId = prop(vars.aforoPropAforoProductId)
var introspectProp = prop(vars.aforoPropIntrospectUrl)
var introspectUrl = if (introspectProp != "") introspectProp
  else if (origin(endpoint) != "") origin(endpoint) ++ "/api/v1/customer-keys/introspect" else ""
var quotaProp = prop(vars.aforoPropQuotaCheckUrl)
var quotaUrl = if (quotaProp != "") quotaProp
  else if (origin(endpoint) != "") origin(endpoint) ++ "/api/v1/quota/check" else ""
var keyHeader = lower(prop(vars.aforoPropKeyHeader))
var productType = upper(prop(vars.aforoPropProductType))
var excludePathEntries = csv(vars.aforoPropExcludePaths)
var excludeStatusEntries = csv(vars.aforoPropExcludeStatusCodes)
var problems =
  (if (endpoint == "") ["aforo-endpoint is not set"] else []) ++
  (if (apiKey == "") ["aforo-api-key is not set"] else []) ++
  (if (productId == "") ["aforo-product-id is not set"] else []) ++
  (if (introspectUrl == "") ["introspect-url is not set and aforo-endpoint has no http(s) origin"] else [])
---
{
  endpoint: endpoint,
  apiKey: apiKey,
  tenantId: prop(vars.aforoPropAforoTenantId),
  productId: productId,
  introspectUrl: introspectUrl,
  introspectTimeoutMs: 1500,
  keyHeader: if (keyHeader == "") "x-api-key" else keyHeader,
  identityTtlS: bounded(vars.aforoPropIdentityCacheTtlS, 60, 0, 3600),
  identityNegativeTtlS: bounded(vars.aforoPropIdentityNegativeTtlS, 10, 0, 600),
  identityStaleTtlS: bounded(vars.aforoPropIdentityStaleTtlS, 900, 0, 86400),
  identityFailOpen: flag(vars.aforoPropIdentityFailOpen, false),
  productType: if (productType == "") "API" else productType,
  defaultMetric: prop(vars.aforoPropDefaultMetric),
  metricRules: metricRules,
  quantityHeader: if (prop(vars.aforoPropQuantityHeader) == "") "X-Aforo-Quantity" else prop(vars.aforoPropQuantityHeader),
  agentId: prop(vars.aforoPropAgentId),
  traceIdHeader: if (prop(vars.aforoPropTraceIdHeader) == "") "X-Aforo-Trace-Id" else prop(vars.aforoPropTraceIdHeader),
  statusOutcomes: statusOutcomes,
  excludePaths:
    if (isEmpty(excludePathEntries)) DEFAULT_EXCLUDE_PATHS
    else if ((sizeOf(excludePathEntries) == 1) and (lower(excludePathEntries[0]) == "none")) []
    else excludePathEntries,
  excludeStatusCodes:
    if (isEmpty(excludeStatusEntries)) DEFAULT_EXCLUDE_STATUS_CODES
    else if ((sizeOf(excludeStatusEntries) == 1) and (lower(excludeStatusEntries[0]) == "none")) []
    else (excludeStatusEntries filter ($ matches /[1-5][0-9][0-9]/)) map ($ as Number),
  quotaEnabled: flag(vars.aforoPropQuotaEnabled, false),
  quotaUrl: quotaUrl,
  quotaTimeoutMs: bounded(vars.aforoPropQuotaTimeoutMs, 1500, 100, 10000),
  quotaFailOpen: flag(vars.aforoPropQuotaFailOpen, true),
  quotaCacheTtlMs: 1000,
  problems: problems,
  warnings:
    (if (mappingsParsed == "invalid") ["metric-mappings is not valid JSON; ignored"] else []) ++
    (badRules map ((r) -> "metric-mappings rule " ++ write(r.pathPattern default null, "application/json") ++ " skipped (no metricName, or not a supported Lua pattern)"))
}












                                %dw 2.0
// aforo-script: mcp-body
// Whether the MCP request body may be read for tools/call detection: only
// with a declared length (Content-Length, no Transfer-Encoding) of at most
// 1 MiB. Anything else is not read, so a large or chunked body is never
// pulled into memory.
output application/java
var MAX_BODY = 1048576
fun header(hs, name) = do {
  var all = valuesOf((if (hs is Object) hs else {}) filterObject ((v, k) -> (v != null) and (lower(k as String) == lower(name))))
  var first = all[0]
  var v = if (first is Array) first[0] else first
  ---
  if (v is String) trim(v) else if (v is Number) (v as String) else null
}
var te = header(attributes.headers, "transfer-encoding")
var cl = header(attributes.headers, "content-length")
---
if (te != null) {read: false, reason: "the request has Transfer-Encoding and no declared length"}
else if ((cl == null) or (not (cl matches /[0-9]{1,10}/))) {read: false, reason: "the request has no usable Content-Length"}
else if ((cl as Number) > MAX_BODY) {read: false, reason: "the request body is over 1 MiB"}
else {read: true, reason: null}























                        %dw 2.0
// aforo-script: request
// Request facts and the billing plan: who is calling (the key and its hash),
// which metric the call bills and whether it bills anything at all. Decided
// once, so the quota pre-flight asks about exactly what metering bills.
import * from dw::Crypto
import toHex from dw::core::Binaries
import charCode from dw::core::Strings
output application/java
var cfg = vars.aforoCfg
var HEX = "0123456789ABCDEF"
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""
// First value of a header, case-insensitive; null when absent.
fun header(hs, name) = do {
  var all = valuesOf((if (hs is Object) hs else {}) filterObject ((v, k) -> (v != null) and (lower(k as String) == lower(name))))
  var first = all[0]
  ---
  if (first == null) null else if (first is Array) str(first[0]) else str(first)
}
fun clean(v, max) =
  if ((v is String) and (v != "") and (sizeOf(v) <= max) and (not (v contains /[\x00-\x1F\x7F]/))) v else null
fun pct(ch) = do {
  var c = charCode(ch)
  ---
  "%" ++ HEX[floor(c / 16)] ++ HEX[c mod 16]
}
// A client value that must stay on the event (a tool name): control
// characters percent-encoded, then cut to max.
fun escaped(v, max) = do {
  var s = if (v is String) (v replace /[\x00-\x1F\x7F]/ with ((m) -> pct(m[0]))) else ""
  ---
  if (sizeOf(s) > max) s[0 to max - 1] else s
}
// "/health" excludes "/health" and "/health/live", not "/healthcare".
fun isExcludedPath(path, entries) = sizeOf(entries filter ((x) ->
  (x != "") and ((path == x) or ((path startsWith x) and ((x endsWith "/") or (path[sizeOf(x)] == "/")))))) > 0

// ── MCP (JSON-RPC 2.0): one entry per tools/call, batches included ──
// params._meta.agent_id is never read: the client does not name the agent.
fun parseJsonRpc(text) =
  if ((not (text is String)) or (text == "") or (sizeOf(text) > 1048576)) null
  else do {
    var parsed = dw::Runtime::try(() -> read(text, "application/json")).result
    var messages = if (parsed is Array) parsed
      else if ((parsed is Object) and (parsed.jsonrpc != null)) [parsed] else []
    var rpc = messages filter ((m) -> (m is Object) and (m.jsonrpc == "2.0"))
    var calls = (rpc filter ((m) -> m.method == "tools/call")) map ((m) -> do {
      var params = if (m.params is Object) m.params else {}
      var name = if (params.name is String) escaped(params.name, 64) else ""
      ---
      {
        toolName: if (name == "") "unknown" else name,
        id: if ((m.id is String) or (m.id is Number)) m.id else null
      }
    })
    ---
    if (isEmpty(rpc)) null else {calls: calls, other: sizeOf(rpc) - sizeOf(calls)}
  }

// ── Metric: metric-mappings (first match), then the fallback ──
fun mappedMetric(method, path) =
  (cfg.metricRules filter ((r) -> ((r.method == "") or (r.method == method)) and (path contains (r.re as Regex))))[0].metricName
var method = upper(str(attributes.method))
var path = if (str(attributes.requestPath) == "") "/" else str(attributes.requestPath)
var defaultMetric = if (cfg.defaultMetric != "") cfg.defaultMetric else "api_calls"
var plainMetric = mappedMetric(method, path) default defaultMetric
// A tools/call: mappings, then an MCP_SERVER product's own default metric
// (unless it is still api_calls), else mcp_server.tool_invocations.
var toolMetric = mappedMetric(method, path) default
  (if ((cfg.defaultMetric != "") and (cfg.defaultMetric != "api_calls")) cfg.defaultMetric else "mcp_server.tool_invocations")

var isMcp = cfg.productType == "MCP_SERVER"
var jsonrpc = if (isMcp and (method == "POST")) parseJsonRpc(vars.aforoRequestText) else null
var tools = isMcp and (jsonrpc != null) and (sizeOf(jsonrpc.calls) > 0)
// MCP_SERVER bills tool calls only: initialize, tools/list, ping and
// notifications are protocol traffic, never billed and never refused.
var plain = not isMcp
var excluded = isExcludedPath(path, cfg.excludePaths)
var cors = (method == "OPTIONS") and (header(attributes.headers, "access-control-request-method") != null)

var rawKey = header(attributes.headers, cfg.keyHeader)
var key = trim(rawKey default "")
var keyProblem = if (key == "") "missing"
  else if ((sizeOf(key) > 1024) or (key contains /[\x00-\x1F\x7F]/)) "invalid" else null
---
{
  requestId: vars.aforoRequestId,
  startMs: vars.aforoStartMs,
  method: method,
  path: path,
  excluded: excluded,
  cors: cors,
  key: if (keyProblem == null) key else null,
  keyHash: if (keyProblem == null) lower(toHex(hashWith(key as Binary {encoding: "UTF-8"}, "SHA-256"))) else null,
  keyProblem: keyProblem,
  // The client's trace context: informational only, it never names the
  // trace and never changes the product type.
  trace: {
    traceparent: clean(header(attributes.headers, "traceparent"), 128),
    tracestate: clean(header(attributes.headers, "tracestate"), 512),
    xTraceId: clean(header(attributes.headers, "x-trace-id"), 128),
    xRequestId: clean(header(attributes.headers, "x-request-id"), 128)
  },
  plan: {
    productType: cfg.productType,
    tools: tools,
    plain: plain,
    calls: if (tools) jsonrpc.calls else [],
    otherMessages: if (jsonrpc != null) jsonrpc.other else 0,
    metric: plainMetric,
    toolMetric: if (tools) toolMetric else null,
    // The pre-flight check: only the metric this call bills, and nothing for
    // a call that bills nothing.
    quotaMetric: if (excluded or cors) null else if (tools) toolMetric else if (plain) plainMetric else null
  }
}









                                #['']











                        %dw 2.0
// aforo-script: identity-lookup
// What the cache knows about this key, and whether Aforo must be asked.
//   fresh positive: age < identity-cache-ttl-s and before expiresAt
//   fresh negative: age < identity-negative-ttl-s
//   stale usable:   positive, age <= identity-stale-ttl-s, before expiresAt
output application/java
var cfg = vars.aforoCfg
var req = vars.aforoReq
var now = req.startMs
var text = if (vars.aforoIdentityCached is String) vars.aforoIdentityCached else ""
var parsed = if (text == "") null else dw::Runtime::try(() -> read(text, "application/json")).result
var entry = if ((parsed is Object) and (parsed.v == 1) and (parsed.storedAtMs is Number) and (parsed.active is Boolean)) parsed else null
var age = if (entry == null) 0 else now - entry.storedAtMs
var beforeExpiry = (entry != null) and ((entry.expiresAtMs == null) or (now < entry.expiresAtMs))
var freshPositive = (entry != null) and (entry.active == true) and beforeExpiry and (age >= 0) and (age < cfg.identityTtlS * 1000)
var freshNegative = (entry != null) and (entry.active == false) and (age >= 0) and (age < cfg.identityNegativeTtlS * 1000)
var staleUsable = (entry != null) and (entry.active == true) and beforeExpiry and (age <= cfg.identityStaleTtlS * 1000)
---
{
  entry: entry,
  fresh: freshPositive or freshNegative,
  staleUsable: staleUsable,
  introspect: isEmpty(cfg.problems) and (req.keyProblem == null) and (not (freshPositive or freshNegative))
}







                                #[output application/json --- {key: vars.aforoReq.key}]
                                #[{'Content-Type': 'application/json', 'X-API-Key': vars.aforoCfg.apiKey}]














                        %dw 2.0
// aforo-script: identity-decide
// The access decision (MC2), and what to cache.
//   outcome "allow"              identified: quota, then upstream, then metered
//   outcome "allow-unidentified" identity-fail-open: upstream, not metered
//   outcome "reject"             answered here: {status, headers, body}
output application/java
var cfg = vars.aforoCfg
var req = vars.aforoReq
var lookup = vars.aforoIdLookup
var resp = vars.aforoIntrospection
var now = req.startMs
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""
fun clean(v, max) =
  if ((v is String) and (v != "") and (sizeOf(v) <= max) and (not (v contains /[\x00-\x1F\x7F]/))) v else null
fun reject(status, message, headers, reason) =
  {outcome: "reject", status: status, headers: headers, body: {message: message}, reason: reason}
fun epochMs(v) =
  if (v is Number) (if (v > 100000000000) v else v * 1000)
  else if ((v is String) and (trim(v) != "")) (
    dw::Runtime::try(() -> (v as DateTime) as Number {unit: "milliseconds"}).result default
    (dw::Runtime::try(() -> ((v as LocalDateTime) ++ |Z|) as Number {unit: "milliseconds"}).result default null))
  else null

// The introspection answer: {kind: active|inactive|failed, ...}.
// {"active":...} or the platform's {"success":..,"data":{"active":...}}.
var answer =
  if (resp == null) {kind: "none"}
  else if (resp.status != 200) {
    kind: "failed",
    reason: if (resp.status == 0) ("no response: " ++ str(resp.error))
      else if ((resp.status == 401) or (resp.status == 403)) ("HTTP " ++ str(resp.status) ++ ": Aforo refused aforo-api-key (it needs scope usage:ingest)")
      else ("HTTP " ++ str(resp.status))
  }
  else do {
    var parsed = dw::Runtime::try(() -> read(str(resp.text), "application/json")).result
    var body = if ((parsed is Object) and (parsed.data is Object)) parsed.data else parsed
    var expiresAtMs = if (body is Object) epochMs(body.expiresAt) else null
    var customerId = if (body is Object) clean(str(body.customerId), 64) else null
    var productIds = if (body is Object)
      (((if (body.productIds is Array) body.productIds else []) ++ (if (body.productId != null) [body.productId] else []))
        map trim(str($))) filter ($ != "")
      else []
    ---
    if (not (body is Object)) {kind: "failed", reason: "unreadable introspection answer"}
    else if (body.active == false) {kind: "inactive"}
    else if (body.active != true) {kind: "failed", reason: "introspection answer has no active field"}
    else if ((expiresAtMs != null) and (expiresAtMs <= now)) {kind: "inactive"}
    else if (customerId == null) {kind: "failed", reason: "active key without a usable customerId"}
    else {
      kind: "active",
      entry: {
        v: 1,
        active: true,
        customerId: customerId,
        productIds: productIds,
        keyId: clean(str(body.keyId), 128),
        subscriptionId: clean(str(body.subscriptionId), 128),
        productType: clean(str(body.productType), 20),
        expiresAtMs: expiresAtMs,
        storedAtMs: now
      }
    }
  }

fun fromEntry(entry, source) =
  if (entry.active != true) reject(401, "Invalid authentication credentials", {}, "inactive key (" ++ source ++ ")")
  else if (not ((entry.productIds default []) contains cfg.productId))
    reject(403, "This API key does not grant access to this API", {}, "key does not cover product " ++ cfg.productId ++ " (" ++ source ++ ")")
  else {
    outcome: "allow",
    source: source,
    identity: {
      customerId: entry.customerId,
      keyId: entry.keyId,
      subscriptionId: entry.subscriptionId
    }
  }

var decision =
  if (not isEmpty(cfg.problems))
    reject(503, "Aforo policy is not configured", {"Retry-After": "60"}, "configuration: " ++ (cfg.problems joinBy "; "))
  else if (req.keyProblem == "missing") reject(401, "No API key found in request", {}, "no key")
  else if (req.keyProblem != null) reject(401, "Invalid authentication credentials", {}, "unusable key")
  else if (lookup.fresh) fromEntry(lookup.entry, "cache")
  else if (answer.kind == "active") fromEntry(answer.entry, "introspection")
  else if (answer.kind == "inactive") reject(401, "Invalid authentication credentials", {}, "inactive key (introspection)")
  else if (lookup.staleUsable) fromEntry(lookup.entry, "stale cache")
  else if (cfg.identityFailOpen) {outcome: "allow-unidentified", source: "fail-open"}
  else reject(503, "Access check unavailable", {"Retry-After": "5"}, "introspection unavailable")

var cacheWrite =
  if (answer.kind == "active")
    (if ((cfg.identityTtlS > 0) or (cfg.identityStaleTtlS > 0)) answer.entry else null)
  else if (answer.kind == "inactive")
    (if (cfg.identityNegativeTtlS > 0) {v: 1, active: false, storedAtMs: now} else null)
  else null

var quota =
  if ((decision.outcome == "allow") and cfg.quotaEnabled and (req.plan.quotaMetric != null) and (cfg.quotaUrl != ""))
    {
      metricName: req.plan.quotaMetric,
      customerId: decision.identity.customerId,
      cacheKey: "quota|" ++ decision.identity.customerId ++ "|" ++ req.plan.quotaMetric
    }
  else null
---
decision ++ {
  cacheWrite: if (cacheWrite == null) null else write(cacheWrite, "application/json", {indent: false}),
  quota: quota,
  warn:
    if (answer.kind == "failed")
      {kind: "introspection", message: "[aforo-metering] introspection failed (" ++ answer.reason ++ "): " ++
        (if (decision.outcome == "allow") "using the cached answer"
         else if (decision.outcome == "allow-unidentified") "identity-fail-open is on, the call passes unchecked and unmetered"
         else "answering " ++ str(decision.status)) ++ ". Repeats suppressed for 60 s."}
    else if ((decision.reason default "") startsWith "configuration")
      {kind: "configuration", message: "[aforo-metering] policy not configured: " ++ (cfg.problems joinBy "; ") ++ ". Every call gets 503."}
    else if (not isEmpty(cfg.warnings))
      {kind: "configuration", message: "[aforo-metering] " ++ (cfg.warnings joinBy "; ")}
    else null
}






