// aforo-script: quota-lookup
// A cached ALLOW or WARN younger than 1 s answers the check; DENY is never
// cached, so a top-up unblocks the customer at once.
output application/java
var now = vars.aforoReq.startMs
var text = if (vars.aforoQuotaCached is String) vars.aforoQuotaCached else ""
var parsed = if (text == "") null else dw::Runtime::try(() -> read(text, "application/json")).result
var fresh = (parsed is Object) and (["ALLOW", "WARN"] contains parsed.decision) and (parsed.storedAtMs is Number)
  and ((now - parsed.storedAtMs) >= 0) and ((now - parsed.storedAtMs) < vars.aforoCfg.quotaCacheTtlMs)
---
{
  call: not fresh,
  cachedDecision: if (fresh) parsed.decision else null
}







                                        #[output application/json --- {customerId: vars.aforoAccess.quota.customerId, metricName: vars.aforoAccess.quota.metricName}]
                                        #[{'Content-Type': 'application/json', 'X-API-Key': vars.aforoCfg.apiKey, 'X-Tenant-Id': vars.aforoCfg.tenantId}]














                                %dw 2.0
// aforo-script: quota-decide
// The answer of POST /api/v1/quota/check, as Kong's preflight-quota.lua reads it:
//   DENY        429, Retry-After = max(1, ceil(retryAfterMs / 1000)) (60 when
//               none), the same number in {message, retryAfter}
//   ALLOW/WARN  let through, cached 1 s
//   no answer   fail open (quota-fail-open, the default), else 503
output application/java
var cfg = vars.aforoCfg
var lookup = vars.aforoQuotaLookup
var resp = vars.aforoQuotaResponse
var now = vars.aforoReq.startMs
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""
var parsed = if ((resp != null) and (resp.status == 200)) dw::Runtime::try(() -> read(str(resp.text), "application/json")).result else null
var data = if ((parsed is Object) and (parsed.data is Object)) parsed.data else parsed
var problem =
  if (not lookup.call) null
  else if (resp == null) "no response"
  else if (resp.status == 0) ("no response: " ++ str(resp.error))
  else if ((resp.status == 401) or (resp.status == 403)) ("HTTP " ++ str(resp.status) ++ ": the ingestor refused aforo-api-key / aforo-tenant-id")
  else if (resp.status != 200) ("HTTP " ++ str(resp.status))
  else if (not ((data is Object) and (data.decision is String))) "no decision in the answer"
  else null
var ms = if ((data is Object) and (data.retryAfterMs is Number)) data.retryAfterMs
  else if (data is Object) (dw::Runtime::try(() -> str(data.retryAfterMs) as Number).result default 0) else 0
var retryAfter = if (ms > 0) max([1, ceil(ms / 1000)]) else 60
// Headers the ingestor asks to pass on (X-RateLimit-*), text values only.
var extraHeaders = if ((data is Object) and (data.headers is Object))
  (data.headers filterObject ((v, k) -> (v is String) or (v is Number))) mapObject ((v, k) -> {(k): str(v)})
  else {}
---
if (not lookup.call) {outcome: "allow", decision: lookup.cachedDecision, source: "cache", cacheWrite: null, warn: null}
else if (problem != null) (
  if (cfg.quotaFailOpen)
    {outcome: "allow", decision: "UNAVAILABLE", source: "fail-open", cacheWrite: null,
     warn: {kind: "quota", message: "[aforo-metering] quota check unavailable (" ++ problem ++ "): failing OPEN, quota NOT enforced. Repeats suppressed for 60 s."}}
  else
    {outcome: "reject", status: 503, headers: {"Retry-After": "1"}, body: {message: "Quota check unavailable"},
     reason: "quota check unavailable", cacheWrite: null,
     warn: {kind: "quota", message: "[aforo-metering] quota check unavailable (" ++ problem ++ "): quota-fail-open is false, answering 503. Repeats suppressed for 60 s."}})
else if (data.decision == "DENY")
  {outcome: "reject", status: 429,
   headers: (extraHeaders - "Retry-After" - "retry-after" - "Content-Type" - "content-type") ++ {"Retry-After": str(retryAfter)},
   body: {message: if ((data.reason is String) and (data.reason != "")) data.reason else "Quota exceeded", retryAfter: retryAfter},
   reason: "quota DENY", cacheWrite: null, warn: null}
else
  {outcome: "allow", decision: data.decision, source: "quota-check",
   cacheWrite: if (["ALLOW", "WARN"] contains data.decision) write({decision: data.decision, storedAtMs: now}, "application/json", {indent: false}) else null,
   warn: null}






