                                                    %dw 2.0
// aforo-script: events
// The usage events of one call, built once. Trusted sources only: the
// introspected customer, the policy configuration, the gateway's own request
// id, and the upstream's RESPONSE headers (the client cannot set them).
//   API          one event
//   AGENTIC_API  traceId = trace-id-header (X-Aforo-Trace-Id), else the request id
//   AI_AGENT     agentId = X-Aforo-Agent-Id, else agent-id, else the product id;
//                sessionId = X-Aforo-Session-Id, else the request id; traceId = sessionId
//   MCP_SERVER   one event per tools/call; agentId = X-Aforo-Agent-Id, else the
//                customer; sessionId = X-Aforo-Session-Id, else the upstream's
//                Mcp-Session-Id (hashed when too long)
// A present but unusable identity header skips the event rather than billing
// a different identity.
import * from dw::Crypto
import toHex from dw::core::Binaries
import charCode from dw::core::Strings
output application/java
var cfg = vars.aforoCfg
var req = vars.aforoReq
var plan = req.plan
var identity = vars.aforoAccess.identity
var MAX = {customerId: 64, metricName: 255, idempotencyKey: 255, agentId: 36, sessionId: 64,
  productType: 20, traceId: 128, toolName: 64}
var REQUIRED = {API: [], AGENTIC_API: ["traceId"], AI_AGENT: ["agentId", "sessionId"], MCP_SERVER: ["toolName", "agentId"]}
var HEX = "0123456789ABCDEF"
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""
fun header(hs, name) = do {
  var all = valuesOf((if (hs is Object) hs else {}) filterObject ((v, k) -> (v != null) and (lower(k as String) == lower(name))))
  var first = all[0]
  ---
  if (first == null) null else if (first is Array) str(first[0]) else str(first)
}
fun clean(v, max) =
  if ((v is String) and (v != "") and (sizeOf(v) <= max) and (not (v contains /[\x00-\x1F\x7F]/))) v else null
fun pct(ch) = do {
  var c = charCode(ch)
  ---
  "%" ++ HEX[floor(c / 16)] ++ HEX[c mod 16]
}
fun escaped(v, max) = do {
  var s = if (v is String) (v replace /[\x00-\x1F\x7F]/ with ((m) -> pct(m[0]))) else ""
  ---
  if (sizeOf(s) > max) s[0 to max - 1] else s
}
// An upstream response header naming who or what is billed:
// {value} usable, {} absent, {bad: name} present but unusable.
fun upstream(name, max) = do {
  var raw = header(attributes.headers, name)
  ---
  if ((raw == null) or (raw == "")) {} else if (clean(raw, max) != null) {value: raw} else {bad: name}
}
fun sha256(s) = lower(toHex(hashWith(s as Binary {encoding: "UTF-8"}, "SHA-256")))
fun outcomeOf(status) =
  if ((not (status is Number)) or (status < 200) or (status > 599)) null
  else if (cfg.statusOutcomes[(floor(status) as String)] != null) cfg.statusOutcomes[(floor(status) as String)]
  else if (status < 400) "SUCCESS"
  else if ((status == 408) or (status == 504)) "TIMEOUT"
  else if (status == 499) "CANCELLED"
  else if ((status == 400) or (status == 422)) "VALIDATION_FAILED"
  else if ((status == 401) or (status == 403) or (status == 429)) "BLOCKED"
  else "ERROR"

var status = if (attributes.statusCode is Number) attributes.statusCode else if (vars.aforoFlowFailed == true) 500 else 0
var requestId = str(req.requestId)
var elapsed = if ((vars.aforoEndMs is Number) and (req.startMs is Number) and (vars.aforoEndMs >= req.startMs)) vars.aforoEndMs - req.startMs else 0
var occurredAt = ((((if (vars.aforoEndMs is Number) vars.aforoEndMs else req.startMs) as DateTime {unit: "milliseconds"}) >> "UTC")
  as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"})
var customerId = if (identity == null) null else clean(str(identity.customerId), MAX.customerId)
var metricHeader = upstream("X-Aforo-Metric", MAX.metricName)

var skipReason =
  if (customerId == null) "no verified customer"
  else if (req.excluded) "excluded path"
  else if (cfg.excludeStatusCodes contains status) "excluded status code"
  else if (req.cors) "CORS preflight"
  else if (requestId == "") "no request id"
  else if ((not plan.tools) and (not plan.plain)) "nothing billable (no tools/call)"
  else if (metricHeader.bad != null) "unusable X-Aforo-Metric response header"
  else null

// ── MCP tool calls ──
var mcpAgent = upstream("X-Aforo-Agent-Id", MAX.agentId)
var mcpSessionHeader = upstream("X-Aforo-Session-Id", MAX.sessionId)
var rawMcpSession = header(attributes.headers, "Mcp-Session-Id")
var mcpSession =
  if (mcpSessionHeader.bad != null) mcpSessionHeader
  else if (mcpSessionHeader.value != null) mcpSessionHeader
  else if ((rawMcpSession == null) or (rawMcpSession == "")) {}
  else if (clean(rawMcpSession, MAX.sessionId) != null) {value: rawMcpSession}
  else {value: "mcp-" ++ (sha256(rawMcpSession)[0 to 55])}
var toolProblem =
  if (not plan.tools) null
  else if (mcpAgent.bad != null) "unusable " ++ mcpAgent.bad ++ " response header"
  else if (mcpSession.bad != null) "unusable " ++ mcpSession.bad ++ " response header"
  else null
var toolEvents = if ((skipReason != null) or (not plan.tools) or (toolProblem != null)) []
  else (plan.calls default []) map ((call, i) -> do {
    var tool = do {
      var t = escaped(str(call.toolName), MAX.toolName)
      ---
      if (t == "") "unknown" else t
    }
    ---
    {
      productType: "MCP_SERVER",
      customerId: customerId,
      metricName: metricHeader.value default plan.toolMetric,
      quantity: 1,
      idempotencyKey: "mcp:" ++ cfg.tenantId ++ ":" ++ requestId ++ ":" ++ ((i + 1) as String) ++ ":" ++ tool,
      occurredAt: occurredAt,
      toolName: tool,
      agentId: mcpAgent.value default customerId,
      (sessionId: mcpSession.value) if (mcpSession.value != null),
      executionDurationMs: elapsed
    }
  })

// ── The call itself (API, AGENTIC_API, AI_AGENT) ──
var quantityRaw = header(attributes.headers, cfg.quantityHeader)
var quantityNum = if ((quantityRaw != null) and (trim(quantityRaw) matches /[0-9]+(\.[0-9]+)?([eE][+-]?[0-9]+)?/))
  dw::Runtime::try(() -> trim(quantityRaw) as Number).result else null
var quantity = if ((quantityNum != null) and (quantityNum > 0)) quantityNum else 1
var aiAgent = upstream("X-Aforo-Agent-Id", MAX.agentId)
var aiSession = upstream("X-Aforo-Session-Id", MAX.sessionId)
var traceHeader = upstream(cfg.traceIdHeader, MAX.traceId)
var plainProblem =
  if (not plan.plain) null
  else if ((plan.productType == "AI_AGENT") and (aiAgent.bad != null)) "unusable " ++ aiAgent.bad ++ " response header"
  else if ((plan.productType == "AI_AGENT") and (aiSession.bad != null)) "unusable " ++ aiSession.bad ++ " response header"
  else if ((plan.productType == "AGENTIC_API") and (traceHeader.bad != null)) "unusable " ++ traceHeader.bad ++ " response header"
  else null
var aiSessionId = aiSession.value default requestId
var plainEvents = if ((skipReason != null) or (not plan.plain) or (plainProblem != null)) []
  else [{
    productType: plan.productType,
    customerId: customerId,
    metricName: metricHeader.value default plan.metric,
    quantity: quantity,
    idempotencyKey: requestId,
    occurredAt: occurredAt,
    (traceId: traceHeader.value default requestId) if (plan.productType == "AGENTIC_API"),
    (agentId: aiAgent.value default (if (cfg.agentId != "") cfg.agentId else clean(cfg.productId, MAX.agentId))) if (plan.productType == "AI_AGENT"),
    (sessionId: aiSessionId) if (plan.productType == "AI_AGENT"),
    (traceId: aiSessionId) if (plan.productType == "AI_AGENT")
  }]

// ── Common fields, then the checks the ingestor would apply ──
var endpointPath = do {
  var p = escaped(req.path, 512)
  ---
  if (p == "") "/" else p
}
var executionStatus = outcomeOf(status)
var built = (toolEvents ++ plainEvents) map ((e) -> e ++ {
  endpointPath: endpointPath,
  httpMethod: if (sizeOf(req.method default "") > 16) req.method[0 to 15] else (req.method default ""),
  statusCode: status,
  responseTimeMs: elapsed,
  (executionStatus: executionStatus) if (executionStatus != null),
  trace: req.trace,
  metadata: {
    gateway: "mulesoft",
    method: req.method,
    path: endpointPath,
    status: status,
    endpoint_path: endpointPath,
    http_method: req.method,
    status_code: status,
    response_time_ms: elapsed,
    productId: cfg.productId,
    (keyId: identity.keyId) if ((identity != null) and (identity.keyId != null))
  }
})
fun problemOf(e) = do {
  var tooLong = (keysOf(MAX) map ($ as String)) filter ((f) -> (e[f] is String) and (sizeOf(e[f]) > MAX[f]))
  var missing = (REQUIRED[e.productType] default []) filter ((f) -> (e[f] == null) or (e[f] == ""))
  var q = e.quantity
  ---
  if (not isEmpty(tooLong)) (tooLong[0] ++ " is longer than " ++ (MAX[tooLong[0]] as String) ++ " characters")
  else if (not isEmpty(missing)) ("productType " ++ e.productType ++ " requires " ++ missing[0])
  else if ((not (q is Number)) or (q <= 0) or (q >= 100000000000000)) "quantity not > 0 or too large"
  else null
}
var checked = built map ((e) -> do {
  var q = if (e.quantity is Number) (round(e.quantity * 1000000) / 1000000) else e.quantity
  var rounded = (e - "quantity") ++ {quantity: q}
  ---
  {event: rounded, problem: problemOf(rounded)}
})
var ready = (checked filter ($.problem == null)) map $.event
var dropped = ((checked filter ($.problem != null)) map $.problem)
  ++ (if (toolProblem != null) [toolProblem] else []) ++ (if (plainProblem != null) [plainProblem] else [])
---
{
  events: ready,
  payload: if (isEmpty(ready)) null else write({events: ready}, "application/json", {indent: false}),
  skipReason: if (skipReason != null) skipReason else if (isEmpty(ready)) (dropped joinBy "; ") else null,
  dropped: dropped
}









                                                                #[vars.aforoEvents.payload]























                                                                                    #['']





                                                                                                #[vars.aforoPendingText]
                                                                                                #[{'Content-Type': 'application/json', 'X-API-Key': vars.aforoCfg.apiKey}]















                                                                                                %dw 2.0
// aforo-script: delivery
// The ingestor's answer to one attempt (vars.aforoAttempt, 1-3):
//   202 {"success":true,"data":{"accepted","failed","errors":[{index,message,retryable}]}}
//     an error with retryable=true (or, from an older ingestor without the
//     flag, a message starting "The event could not be stored") is
//     transient: that event is re-sent; any other is permanent: logged and
//     dropped. errors[] is read even when "failed" is missing or 0.
//   no answer, 408, 429 or any 5xx: the whole batch is re-sent
//   any other status: the ingestor refused the request (key, URL): logged
// retryDelayMs, the wait before the next attempt (0 when nothing is
// re-sent): max(Retry-After, random(0, min(MAX_BACKOFF_MS, BASE_MS x
// 2^attempt))), at most MAX_RETRY_AFTER_MS. Retry-After is read as
// delta-seconds (fractional allowed) or an HTTP-date; an unreadable value
// is ignored. vars.aforoJitter (0..1) and vars.aforoNowMs are set by the
// template just before this script, so the tests can fix them.
output application/java
fun str(v) = if (v is String) v else if ((v is Number) or (v is Boolean)) (v as String) else ""
var TRANSIENT = "The event could not be stored"
var BASE_MS = 500
var MAX_BACKOFF_MS = 30000
var MAX_RETRY_AFTER_MS = 60000
var pending = dw::Runtime::try(() -> read(str(vars.aforoPendingText), "application/json")).result
var events = if ((pending is Object) and (pending.events is Array)) pending.events else []
var resp = vars.aforoIngestResponse
var status = if (resp.status is Number) resp.status else 0
var body = dw::Runtime::try(() -> read(str(resp.text), "application/json")).result
var errors =
  if ((body is Object) and (body.data is Object) and (body.data.errors is Array)) body.data.errors
  else if ((body is Object) and (body.errors is Array)) body.errors
  else []
var indexed = (errors filter ((e) -> (e is Object) and (e.index is Number)))
  map ((e) -> {index: e.index, message: str(e.message),
    transient: if (e.retryable is Boolean) (e.retryable == true) else (str(e.message) startsWith TRANSIENT)})
var transientIdx = (indexed filter $.transient) map $.index
var permanent = indexed filter (not $.transient)
fun describe(i) = do {
  var e = events[i]
  ---
  if (e is Object) (str(e.metricName) ++ " " ++ str(e.idempotencyKey)) else ("event " ++ (i as String))
}
var wholeRetry = (status == 0) or (status == 408) or (status == 429) or ((status >= 500) and (status <= 599))
var refusedBatch = (not wholeRetry) and ((status < 200) or (status >= 300))
var retryEvents =
  if (wholeRetry) events
  else if (refusedBatch) []
  else (transientIdx map events[$]) filter ($ != null)
var refused =
  if (refusedBatch) ["the ingestor refused the batch (HTTP " ++ (status as String) ++ "; check aforo-api-key and aforo-endpoint): " ++
    (do { var t = str(resp.text) --- if (sizeOf(t) > 300) t[0 to 299] else t })]
  else permanent map ((p) -> describe(p.index) ++ ": " ++ p.message)
var attempt = if ((vars.aforoAttempt is Number) and (vars.aforoAttempt >= 1)) vars.aforoAttempt else 1
var jitter = if ((vars.aforoJitter is Number) and (vars.aforoJitter >= 0) and (vars.aforoJitter < 1)) vars.aforoJitter else 1
var nowMs = if (vars.aforoNowMs is Number) vars.aforoNowMs else (now() as Number {unit: "milliseconds"})
var backoffMs = floor(jitter * min([MAX_BACKOFF_MS, BASE_MS * (2 pow attempt)]))
var retryAfterText = trim(str(if (resp.retryAfter is Array) resp.retryAfter[0] else resp.retryAfter))
var retryAfterSeconds = dw::Runtime::try(() -> retryAfterText as Number).result
var retryAfterAt = dw::Runtime::try(() -> (retryAfterText as DateTime {format: "EEE, dd MMM yyyy HH:mm:ss zzz", locale: "en"}) as Number {unit: "milliseconds"}).result
var retryAfterMs =
  if (retryAfterText == "") 0
  else if (retryAfterSeconds is Number) (if (retryAfterSeconds > 0) ceil(retryAfterSeconds * 1000) else 0)
  else if (retryAfterAt is Number) max([0, retryAfterAt - nowMs])
  else 0
---
{
  status: status,
  retryText: if (isEmpty(retryEvents)) null else write({events: retryEvents}, "application/json", {indent: false}),
  retryDelayMs: if (isEmpty(retryEvents)) 0 else min([MAX_RETRY_AFTER_MS, max([retryAfterMs, backoffMs])]),
  retryReason: if (status == 0) ("no answer from the ingestor (" ++ (if (str(resp.noAnswer) != "") str(resp.noAnswer) else "no response") ++ ")")
    else if (wholeRetry) ("the ingestor answered HTTP " ++ (status as String))
    else ((sizeOf(retryEvents) as String) ++ " event(s) could not be stored"),
  refusedLog: if (isEmpty(refused)) null
    else "[aforo-metering] USAGE EVENT REFUSED (permanent, not retried): " ++ (refused joinBy " | ")
}










                                                                                                    #[vars.aforoDelivery.retryText]




































                                                                    #[0]





                                                                            #[vars.aforoEndMs]



































                                        %dw 2.0
